#include "training.h"
#include "table.h"

/* Reads a training file to use for gene prediction */

int read_training_file(char *fn, struct _training *tinf) {
  size_t rv;
  FILE *fh;
  fh = fopen(fn, "rb");
  if(fh == NULL) return 1;
  rv = fread(tinf, 1, sizeof(struct _training), fh);
  if(rv != sizeof(struct _training)) {
    if(rv == sizeof(struct _training_v0)) /* old format */
      id_to_table(tinf->table, tinf->trans_table);
    else
      return -1;
  }
  fclose(fh);
  return 0;
}

/* Writes a training file to use for a later run of gene prediction */

int write_training_file(char *fn, const struct _training *tinf) {
  size_t rv;
  FILE *fh;
  fh = fopen(fn, "wb");
  if(fh == NULL) return -1;
  rv = fwrite(tinf, sizeof(struct _training), 1, fh);
  fclose(fh);
  if(rv != 1) return -1;
  return 0;
}

